screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const TABLE_CONTRACTS = 0;
  const TABLE_DELIVERABLES = 1;
  const TABLE_DELIVERABLE_DEADLINES = 2;
  const TABLE_DEADLINE_CHANGES = 3;

  let selectedDeliverableId = null;
  let selectedContractId = null;
  let deliverables = [];
  let deadlineChanges = [];

  // ========== ユーティリティ関数 ==========
  function showNotification(type, message) {
    const notif = container.querySelector(`#${type}-notification`);
    const msgEl = notif.querySelector(`#${type}-message`);
    msgEl.textContent = message;
    notif.style.display = 'block';
    setTimeout(() => { notif.style.display = 'none'; }, 4000);
  }

  function formatDate(dateStr) {
    if (!dateStr) return '-';
    const d = new Date(dateStr);
    return d.toLocaleDateString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit' });
  }

  function closeConfirmDialog() {
    container.querySelector('#confirm-dialog-overlay').style.display = 'none';
  }

  function showConfirmDialog(title, message, onConfirm) {
    const overlay = container.querySelector('#confirm-dialog-overlay');
    container.querySelector('#confirm-title').textContent = title;
    container.querySelector('#confirm-message').textContent = message;

    const okBtn = container.querySelector('#confirm-ok-btn');
    const cancelBtn = container.querySelector('[data-testid="confirm-cancel-btn"]');

    okBtn.onclick = () => {
      closeConfirmDialog();
      onConfirm();
    };
    cancelBtn.onclick = closeConfirmDialog;

    overlay.style.display = 'flex';
  }

  // ========== 契約選択 ==========
  async function loadContracts() {
    const contracts = await window.aivicApi.list(TABLE_CONTRACTS);
    if (!contracts) return;

    const select = container.querySelector('[data-testid="contract-select"]');
    select.innerHTML = '<option value="">-- 契約を選択してください --</option>';

    contracts.forEach(c => {
      const opt = document.createElement('option');
      opt.value = c.id || c.contractId;
      opt.textContent = `${c.contractName || c.name} (${c.contractId})`;
      select.appendChild(opt);
    });
  }

  // ========== 成果物一覧読込 ==========
  async function loadDeliverables() {
    selectedContractId = container.querySelector('[data-testid="contract-select"]').value;
    if (!selectedContractId) {
      showNotification('error', '契約を選択してください');
      return;
    }

    const allDeliverables = await window.aivicApi.list(TABLE_DELIVERABLES);
    if (!allDeliverables) return;

    deliverables = allDeliverables.filter(d => d.contractId === selectedContractId);

    const listDiv = container.querySelector('#deliverables-list');
    listDiv.innerHTML = '';

    if (deliverables.length === 0) {
      listDiv.innerHTML = '<div style="color: var(--text-muted); font-size: 12px; text-align: center; padding: 20px;">成果物がありません</div>';
      container.querySelector('#deliverable-detail').style.display = 'none';
      container.querySelector('#change-form-section').style.display = 'none';
      container.querySelector('#no-history-msg').style.display = 'block';
      container.querySelector('#change-history-timeline').innerHTML = '';
      return;
    }

    deliverables.forEach(d => {
      const row = document.createElement('div');
      row.dataset.id = d.id || d.deliverableId;
      row.style.cssText = `
        padding: 10px;
        border: 1px solid var(--border);
        border-radius: 4px;
        background: var(--bg-main);
        cursor: pointer;
        transition: all 0.2s;
      `;
      row.onmouseover = () => { row.style.background = 'var(--bg-hover)'; };
      row.onmouseout = () => { row.style.background = 'var(--bg-main)'; };

      const statusColor = d.status === '完了' ? 'var(--success)' : 
                          d.status === '進行中' ? 'var(--info)' : 'var(--warning)';

      row.innerHTML = `
        <div style="font-size: 12px; font-weight: 500; color: var(--text); margin-bottom: 4px;">${d.name || d.deliverableName}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">納期: ${formatDate(d.deadline || d.plannedDeadline)}</div>
        <div style="display: flex; gap: 6px; align-items: center;">
          <span style="font-size: 10px; padding: 2px 6px; background: ${statusColor}; color: #fff; border-radius: 3px;">${d.status || '計画中'}</span>
        </div>
      `;

      row.onclick = () => selectDeliverable(d);
      listDiv.appendChild(row);
    });
  }

  // ========== 成果物選択 ==========
  async function selectDeliverable(deliverable) {
    selectedDeliverableId = deliverable.id || deliverable.deliverableId;

    // 詳細表示
    container.querySelector('#detail-name').textContent = deliverable.name || deliverable.deliverableName;
    container.querySelector('#detail-status').textContent = deliverable.status || '計画中';
    container.querySelector('#detail-current-date').textContent = formatDate(deliverable.deadline || deliverable.plannedDeadline);
    container.querySelector('#detail-planned-date').textContent = formatDate(deliverable.plannedDeadline);
    container.querySelector('#detail-description').textContent = deliverable.description || '-';

    container.querySelector('#deliverable-detail').style.display = 'block';
    container.querySelector('#change-form-section').style.display = 'block';

    // フォームリセット
    container.querySelector('#change-request-form').reset();

    // 変更履歴読込
    await loadChangeHistory();
  }

  // ========== 変更履歴読込 ==========
  async function loadChangeHistory() {
    const allChanges = await window.aivicApi.list(TABLE_DEADLINE_CHANGES);
    if (!allChanges) return;

    deadlineChanges = allChanges.filter(c => 
      c.deliverableDeadlineId === selectedDeliverableId || 
      c.contractId === selectedContractId
    );

    const timeline = container.querySelector('#change-history-timeline');
    const noMsg = container.querySelector('#no-history-msg');

    if (deadlineChanges.length === 0) {
      timeline.innerHTML = '';
      noMsg.style.display = 'block';
      return;
    }

    noMsg.style.display = 'none';
    timeline.innerHTML = '';

    deadlineChanges.forEach((change, idx) => {
      const item = document.createElement('div');
      item.style.cssText = `
        padding: 10px;
        border-left: 3px solid var(--primary);
        background: var(--bg-main);
        border-radius: 4px;
        font-size: 11px;
      `;

      const statusColor = change.approvalStatus === '承認' ? 'var(--success)' : 
                          change.approvalStatus === '申請中' ? 'var(--warning)' : 'var(--error)';

      item.innerHTML = `
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;">
          <span style="font-weight: 500; color: var(--text);">
            ${formatDate(change.previousDeadline)} → ${formatDate(change.newDeadline)}
          </span>
          <span style="padding: 2px 6px; background: ${statusColor}; color: #fff; border-radius: 3px; font-size: 10px;">
            ${change.approvalStatus || '申請中'}
          </span>
        </div>
        <div style="color: var(--text-muted); margin-bottom: 4px;">理由: ${change.changeReason || '-'}</div>
        <div style="color: var(--text-muted); font-size: 10px;">
          申請: ${formatDate(change.createdAt)} 
          ${change.approvalDate ? `| 承認: ${formatDate(change.approvalDate)}` : ''}
        </div>
        ${change.approvalComment ? `<div style="color: var(--text-muted); margin-top: 4px; font-style: italic;">コメント: ${change.approvalComment}</div>` : ''}
      `;

      timeline.appendChild(item);
    });
  }

  // ========== 納期変更申請送信 ==========
  container.querySelector('#change-request-form').onsubmit = async (e) => {
    e.preventDefault();

    if (!selectedDeliverableId) {
      showNotification('error', '成果物を選択してください');
      return;
    }

    const newDeadline = container.querySelector('[data-testid="new-deadline-input"]').value;
    const changeReason = container.querySelector('[data-testid="change-reason-input"]').value;

    if (!newDeadline || !changeReason) {
      showNotification('error', '新納期と変更理由を入力してください');
      return;
    }

    showConfirmDialog(
      '納期変更申請',
      `新納期: ${formatDate(newDeadline)}\n理由: ${changeReason}\n\nこの内容で申請してよろしいですか？`,
      async () => {
        const changeRecord = {
          deliverableDeadlineId: selectedDeliverableId,
          contractId: selectedContractId,
          previousDeadline: container.querySelector('#detail-current-date').textContent,
          newDeadline: newDeadline,
          changeReason: changeReason,
          approvalStatus: '申請中',
          createdAt: new Date().toISOString(),
          createdBy: 'current-user'
        };

        const saved = await window.aivicApi.save(TABLE_DEADLINE_CHANGES, changeRecord);
        if (saved) {
          showNotification('success', '納期変更申請を送信しました');
          container.querySelector('#change-request-form').reset();
          await loadChangeHistory();
        } else {
          showNotification('error', '申請送信に失敗しました');
        }
      }
    );
  };

  // ========== キャンセルボタン ==========
  container.querySelector('[data-testid="cancel-change-btn"]').onclick = () => {
    container.querySelector('#change-request-form').reset();
  };

  // ========== 読込ボタン ==========
  container.querySelector('[data-testid="load-contract-btn"]').onclick = loadDeliverables;

  // ========== ダッシュボードへ戻る ==========
  container.querySelector('[data-testid="back-to-dashboard"]').onclick = () => {
    window.showScreen('scr-1782623533329');
  };

  // ========== 初期化 ==========
  (async () => {
    await loadContracts();
  })();
}

function(container, apiUrl, tables) {
  const contractSelect = container.querySelector('[data-testid="contract-select"]');
  const customerSelect = container.querySelector('[data-testid="customer-select"]');
  const invoiceList = container.querySelector('#invoice-list');
  const deliverableList = container.querySelector('#deliverable-list');
  const userList = container.querySelector('#user-list');
  const previewPanel = container.querySelector('#preview-panel');
  const messageBanner = container.querySelector('#message-banner');
  const deliveryDatetime = container.querySelector('[data-testid="delivery-datetime"]');
  const emailNotifyCheck = container.querySelector('[data-testid="email-notify-check"]');
  const deliveryMessage = container.querySelector('[data-testid="delivery-message"]');
  const historyTbody = container.querySelector('#history-tbody');

  let currentStep = 1;
  let selectedContract = null;
  let selectedCustomer = null;
  let selectedInvoices = [];
  let selectedDeliverables = [];
  let selectedUsers = [];

  // ステップナビゲーション
  const stepIndicators = container.querySelectorAll('.step-indicator');
  const stepPanels = container.querySelectorAll('.step-panel');

  function showStep(step) {
    currentStep = step;
    stepPanels.forEach(p => p.style.display = 'none');
    container.querySelector(`.step-panel[data-step="${step}"]`).style.display = 'block';

    stepIndicators.forEach((ind, idx) => {
      const stepNum = parseInt(ind.dataset.step);
      if (stepNum < step) {
        ind.style.background = var('--primary');
        ind.style.color = '#000';
      } else if (stepNum === step) {
        ind.style.background = var('--primary');
        ind.style.color = '#000';
      } else {
        ind.style.background = 'var(--border)';
        ind.style.color = 'var(--text)';
      }
    });

    updatePreview();
  }

  // ステップボタン
  stepIndicators.forEach(ind => {
    ind.addEventListener('click', () => {
      const step = parseInt(ind.dataset.step);
      if (step <= currentStep) showStep(step);
    });
  });

  container.querySelector('[data-testid="step1-next"]').addEventListener('click', () => {
    if (!selectedContract || selectedInvoices.length === 0 && selectedDeliverables.length === 0) {
      showMessage('契約と配信対象を選択してください', 'error');
      return;
    }
    showStep(2);
  });

  container.querySelector('[data-testid="step2-prev"]').addEventListener('click', () => showStep(1));
  container.querySelector('[data-testid="step2-next"]').addEventListener('click', () => {
    if (!selectedCustomer || selectedUsers.length === 0) {
      showMessage('顧客企業とユーザーを選択してください', 'error');
      return;
    }
    showStep(3);
  });

  container.querySelector('[data-testid="step3-prev"]').addEventListener('click', () => showStep(2));

  // 契約選択
  contractSelect.addEventListener('change', async (e) => {
    selectedContract = e.target.value;
    selectedInvoices = [];
    selectedDeliverables = [];

    if (!selectedContract) {
      invoiceList.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); padding: 8px; text-align: center;">契約を選択してください</div>';
      deliverableList.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); padding: 8px; text-align: center;">契約を選択してください</div>';
      return;
    }

    // 請求書取得（テーブルインデックス: 請求書テーブル）
    const invoices = await window.aivicApi.list(7); // 請求書テーブル
    const contractInvoices = invoices ? invoices.filter(inv => inv.契約ID === selectedContract) : [];

    invoiceList.innerHTML = contractInvoices.length > 0 
      ? contractInvoices.map(inv => `
          <label style="display: flex; align-items: center; gap: 8px; padding: 6px; cursor: pointer; border-bottom: 1px solid var(--border);">
            <input type="checkbox" class="invoice-checkbox" value="${inv.請求書ID}" data-name="${inv.請求書番号}" style="accent-color: var(--primary);" />
            <span style="font-size: 12px; color: var(--text);">${inv.請求書番号} - ¥${inv.請求金額合計}</span>
          </label>
        `).join('')
      : '<div style="font-size: 12px; color: var(--text-muted); padding: 8px; text-align: center;">請求書がありません</div>';

    // 成果物取得（テーブルインデックス: 成果物テーブル）
    const deliverables = await window.aivicApi.list(5); // 成果物テーブル
    const contractDeliverables = deliverables ? deliverables.filter(del => del.契約ID === selectedContract) : [];

    deliverableList.innerHTML = contractDeliverables.length > 0
      ? contractDeliverables.map(del => `
          <label style="display: flex; align-items: center; gap: 8px; padding: 6px; cursor: pointer; border-bottom: 1px solid var(--border);">
            <input type="checkbox" class="deliverable-checkbox" value="${del.成果物ID}" data-name="${del.成果物名}" style="accent-color: var(--primary);" />
            <span style="font-size: 12px; color: var(--text);">${del.成果物名} (${del.ステータス})</span>
          </label>
        `).join('')
      : '<div style="font-size: 12px; color: var(--text-muted); padding: 8px; text-align: center;">成果物がありません</div>';

    // チェックボックスリスナー
    container.querySelectorAll('.invoice-checkbox').forEach(cb => {
      cb.addEventListener('change', (e) => {
        if (e.target.checked) {
          selectedInvoices.push({ id: e.target.value, name: e.target.dataset.name });
        } else {
          selectedInvoices = selectedInvoices.filter(inv => inv.id !== e.target.value);
        }
        updatePreview();
      });
    });

    container.querySelectorAll('.deliverable-checkbox').forEach(cb => {
      cb.addEventListener('change', (e) => {
        if (e.target.checked) {
          selectedDeliverables.push({ id: e.target.value, name: e.target.dataset.name });
        } else {
          selectedDeliverables = selectedDeliverables.filter(del => del.id !== e.target.value);
        }
        updatePreview();
      });
    });

    updatePreview();
  });

  // 顧客企業選択
  customerSelect.addEventListener('change', async (e) => {
    selectedCustomer = e.target.value;
    selectedUsers = [];

    if (!selectedCustomer) {
      userList.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); padding: 8px; text-align: center;">顧客企業を選択してください</div>';
      return;
    }

    // ログインユーザー取得（テーブルインデックス: ログインユーザーテーブル）
    const users = await window.aivicApi.list(10); // ログインユーザーテーブル
    const customerUsers = users ? users.filter(u => u.顧客企業ID === selectedCustomer) : [];

    userList.innerHTML = customerUsers.length > 0
      ? customerUsers.map(user => `
          <label style="display: flex; align-items: center; gap: 8px; padding: 6px; cursor: pointer; border-bottom: 1px solid var(--border);">
            <input type="checkbox" class="user-checkbox" value="${user.ユーザーID}" data-name="${user.ユーザー名}" data-email="${user.メールアドレス}" style="accent-color: var(--primary);" />
            <span style="font-size: 12px; color: var(--text);">${user.ユーザー名} (${user.メールアドレス})</span>
          </label>
        `).join('')
      : '<div style="font-size: 12px; color: var(--text-muted); padding: 8px; text-align: center;">ユーザーがありません</div>';

    container.querySelectorAll('.user-checkbox').forEach(cb => {
      cb.addEventListener('change', (e) => {
        if (e.target.checked) {
          selectedUsers.push({ id: e.target.value, name: e.target.dataset.name, email: e.target.dataset.email });
        } else {
          selectedUsers = selectedUsers.filter(u => u.id !== e.target.value);
        }
        updatePreview();
      });
    });

    updatePreview();
  });

  // プレビュー更新
  function updatePreview() {
    let preview = '<div style="font-size: 13px; color: var(--text); line-height: 1.6;">';

    if (selectedContract) {
      preview += `<div style="margin-bottom: 12px;"><strong>契約:</strong> ${selectedContract}</div>`;
    }

    if (selectedInvoices.length > 0) {
      preview += `<div style="margin-bottom: 12px;"><strong>請求書 (${selectedInvoices.length}件):</strong><br/>`;
      selectedInvoices.forEach(inv => {
        preview += `<div style="margin-left: 12px; font-size: 12px; color: var(--text-muted);">• ${inv.name}</div>`;
      });
      preview += '</div>';
    }

    if (selectedDeliverables.length > 0) {
      preview += `<div style="margin-bottom: 12px;"><strong>成果物 (${selectedDeliverables.length}件):</strong><br/>`;
      selectedDeliverables.forEach(del => {
        preview += `<div style="margin-left: 12px; font-size: 12px; color: var(--text-muted);">• ${del.name}</div>`;
      });
      preview += '</div>';
    }

    if (selectedCustomer) {
      preview += `<div style="margin-bottom: 12px;"><strong>配信先企業:</strong> ${selectedCustomer}</div>`;
    }

    if (selectedUsers.length > 0) {
      preview += `<div style="margin-bottom: 12px;"><strong>配信先ユーザー (${selectedUsers.length}名):</strong><br/>`;
      selectedUsers.forEach(user => {
        preview += `<div style="margin-left: 12px; font-size: 12px; color: var(--text-muted);">• ${user.name} (${user.email})</div>`;
      });
      preview += '</div>';
    }

    if (deliveryDatetime.value) {
      preview += `<div style="margin-bottom: 12px;"><strong>配信日時:</strong> ${new Date(deliveryDatetime.value).toLocaleString('ja-JP')}</div>`;
    }

    if (emailNotifyCheck.checked) {
      preview += `<div style="margin-bottom: 12px;"><strong>メール通知:</strong> 送信予定</div>`;
    }

    preview += '</div>';
    previewPanel.innerHTML = preview;
  }

  // 配信実行
  container.querySelector('[data-testid="execute-delivery"]').addEventListener('click', async () => {
    if (!selectedContract || selectedInvoices.length === 0 && selectedDeliverables.length === 0 || !selectedCustomer || selectedUsers.length === 0) {
      showMessage('すべての項目を選択してください', 'error');
      return;
    }

    const deliveryData = {
      契約ID: selectedContract,
      顧客企業ID: selectedCustomer,
      請求書IDs: selectedInvoices.map(i => i.id),
      成果物IDs: selectedDeliverables.map(d => d.id),
      配信先ユーザーIDs: selectedUsers.map(u => u.id),
      配信日時: deliveryDatetime.value || new Date().toISOString(),
      メール通知: emailNotifyCheck.checked,
      配信メッセージ: deliveryMessage.value,
      配信ステータス: '送信済',
      作成日時: new Date().toISOString()
    };

    // 通知履歴テーブルに保存（テーブルインデックス: 通知履歴テーブル）
    const saved = await window.aivicApi.save(9, deliveryData); // 通知履歴テーブル

    if (saved) {
      showMessage('配信が完了しました', 'success');
      loadDeliveryHistory();
      setTimeout(() => {
        contractSelect.value = '';
        customerSelect.value = '';
        selectedContract = null;
        selectedCustomer = null;
        selectedInvoices = [];
        selectedDeliverables = [];
        selectedUsers = [];
        deliveryDatetime.value = '';
        emailNotifyCheck.checked = false;
        deliveryMessage.value = '';
        showStep(1);
        invoiceList.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); padding: 8px; text-align: center;">契約を選択してください</div>';
        deliverableList.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); padding: 8px; text-align: center;">契約を選択してください</div>';
        userList.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); padding: 8px; text-align: center;">顧客企業を選択してください</div>';
        updatePreview();
      }, 2000);
    } else {
      showMessage('配信に失敗しました', 'error');
    }
  });

  // 配信履歴読み込み
  async function loadDeliveryHistory() {
    const history = await window.aivicApi.list(9); // 通知履歴テーブル
    if (history && history.length > 0) {
      const recentHistory = history.slice(-5).reverse();
      historyTbody.innerHTML = recentHistory.map(h => `
        <tr style="border-bottom: 1px solid var(--border);">
          <td style="padding: 8px; color: var(--text); font-size: 12px;">${new Date(h.送信日時).toLocaleString('ja-JP')}</td>
          <td style="padding: 8px; color: var(--text); font-size: 12px;">${h.送信状態}</td>
        </tr>
      `).join('');
    }
  }

  // メッセージ表示
  function showMessage(text, type) {
    messageBanner.textContent = text;
    messageBanner.style.display = 'block';
    messageBanner.style.background = type === 'success' ? 'var(--success)' : 'var(--error)';
    messageBanner.style.color = '#fff';
    setTimeout(() => {
      messageBanner.style.display = 'none';
    }, 3000);
  }

  // 初期化
  showStep(1);
  loadDeliveryHistory();
}

function(container, apiUrl, tables) {
  // テーブルインデックス（tables 配列内の位置）
  const contractIdx = 0;
  const proposalIdx = 1;
  const deliverableIdx = 2;
  const customerIdx = 3;
  const notificationHistoryIdx = 4;

  // DOM 要素取得
  const saveBtn = container.querySelector('[data-testid="save-publish-config"]');
  const previewBtn = container.querySelector('[data-testid="preview-publish"]');
  const previewModal = container.querySelector('#preview-modal');
  const closePreviewBtn = container.querySelector('[data-testid="close-preview-modal"]');
  const confirmPreviewBtn = container.querySelector('[data-testid="confirm-preview"]');
  const cancelPreviewBtn = container.querySelector('[data-testid="cancel-preview"]');
  const toggleFailureLogBtn = container.querySelector('[data-testid="toggle-failure-log"]');
  const failureLogPanel = container.querySelector('#failure-log-panel');
  const failureLogToggleIcon = container.querySelector('#failure-log-toggle-icon');
  const failureLogCount = container.querySelector('#failure-log-count');
  const failureLogTbody = container.querySelector('#failure-log-tbody');
  const publishScheduleTimeline = container.querySelector('#publish-schedule-timeline');
  const publishHistoryList = container.querySelector('#publish-history-list');
  const previewContent = container.querySelector('#preview-content');

  // 状態管理
  let currentConfig = {};
  let failureLogExpanded = false;

  // 初期化: 掲載予定と履歴を読み込み
  async function initializePublishData() {
    try {
      const notifications = await window.aivicApi.list(notificationHistoryIdx);
      if (!notifications) return;

      // 掲載予定（送信待ち）
      const scheduled = notifications.filter(n => n.送信状態 === '保留中' || n.送信状態 === '送信待ち');
      renderScheduleTimeline(scheduled);

      // 掲載済み履歴（送信済）
      const completed = notifications.filter(n => n.送信状態 === '送信済');
      renderPublishHistory(completed);

      // 配信失敗ログ
      const failed = notifications.filter(n => n.送信状態 === '送信失敗');
      renderFailureLog(failed);
    } catch (e) {
      console.error('Failed to load publish data:', e);
    }
  }

  // 掲載予定タイムライン描画
  function renderScheduleTimeline(scheduled) {
    publishScheduleTimeline.innerHTML = '';
    if (scheduled.length === 0) {
      publishScheduleTimeline.innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">掲載予定なし</div>';
      return;
    }
    scheduled.forEach(item => {
      const timelineItem = document.createElement('div');
      timelineItem.style.cssText = 'display: flex; gap: 8px; padding: 8px; background: rgba(212, 175, 55, 0.08); border-left: 3px solid var(--primary); border-radius: 4px;';
      timelineItem.innerHTML = `
        <div style="flex: 1;">
          <div style="font-weight: 600; color: var(--text);">${item.通知タイトル || '掲載予定'}</div>
          <div style="color: var(--text-muted); font-size: 11px; margin-top: 2px;">
            企業: ${item.顧客企業ID || '-'} | 予定: ${new Date(item.送信日時).toLocaleString('ja-JP')}
          </div>
        </div>
      `;
      publishScheduleTimeline.appendChild(timelineItem);
    });
  }

  // 掲載済み履歴描画
  function renderPublishHistory(completed) {
    publishHistoryList.innerHTML = '';
    if (completed.length === 0) {
      publishHistoryList.innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">掲載履歴なし</div>';
      return;
    }
    completed.slice(0, 5).forEach(item => {
      const historyItem = document.createElement('div');
      historyItem.style.cssText = 'display: flex; gap: 8px; padding: 6px; background: rgba(124, 179, 66, 0.08); border-left: 3px solid #7cb342; border-radius: 4px;';
      historyItem.innerHTML = `
        <div style="flex: 1;">
          <div style="font-weight: 600; color: var(--text); font-size: 11px;">${item.通知タイトル || '掲載完了'}</div>
          <div style="color: var(--text-muted); font-size: 10px; margin-top: 1px;">
            ${new Date(item.送信日時).toLocaleString('ja-JP')}
          </div>
        </div>
      `;
      publishHistoryList.appendChild(historyItem);
    });
  }

  // 配信失敗ログ描画
  function renderFailureLog(failed) {
    failureLogCount.textContent = failed.length;
    failureLogTbody.innerHTML = '';
    failed.forEach(item => {
      const row = document.createElement('tr');
      row.style.borderBottom = '1px solid var(--border)';
      row.innerHTML = `
        <td style="padding: 4px; color: var(--text-muted);">${new Date(item.送信日時).toLocaleString('ja-JP')}</td>
        <td style="padding: 4px; color: var(--text-muted);">${item.顧客企業ID || '-'}</td>
        <td style="padding: 4px; color: #ef5350;">${item.送信失敗理由 || 'Unknown'}</td>
      `;
      failureLogTbody.appendChild(row);
    });
  }

  // 設定を保存
  saveBtn.addEventListener('click', async () => {
    const includeContracts = container.querySelector('[data-testid="include-contracts"]').checked;
    const includeProposals = container.querySelector('[data-testid="include-proposals"]').checked;
    const includeDeliverables = container.querySelector('[data-testid="include-deliverables"]').checked;
    const targetCompanyId = container.querySelector('[data-testid="target-company-select"]').value;
    const publishStartDatetime = container.querySelector('[data-testid="publish-start-datetime"]').value;
    const publishEndDatetime = container.querySelector('[data-testid="publish-end-datetime"]').value;
    const autoRuleTrigger = container.querySelector('[data-testid="auto-rule-trigger"]').value;
    const enableAutoRule = container.querySelector('[data-testid="enable-auto-rule"]').checked;

    currentConfig = {
      includeContracts,
      includeProposals,
      includeDeliverables,
      targetCompanyId,
      publishStartDatetime,
      publishEndDatetime,
      autoRuleTrigger,
      enableAutoRule,
      savedAt: new Date().toISOString()
    };

    // ローカルストレージに保存（簡易実装）
    localStorage.setItem('portalPublishConfig', JSON.stringify(currentConfig));
    alert('掲載設定を保存しました');
  });

  // プレビュー表示
  previewBtn.addEventListener('click', () => {
    const config = currentConfig;
    let previewHtml = '<div style="line-height: 1.8;">';
    previewHtml += '<div style="margin-bottom: 12px;"><strong>掲載対象:</strong></div>';
    previewHtml += '<ul style="margin: 0; padding-left: 20px;">';
    if (config.includeContracts) previewHtml += '<li>契約書</li>';
    if (config.includeProposals) previewHtml += '<li>提案資料</li>';
    if (config.includeDeliverables) previewHtml += '<li>成果物</li>';
    previewHtml += '</ul>';
    previewHtml += `<div style="margin-top: 12px;"><strong>対象企業:</strong> ${config.targetCompanyId || '全企業'}</div>`;
    previewHtml += `<div style="margin-top: 8px;"><strong>掲載開始:</strong> ${config.publishStartDatetime || '-'}</div>`;
    if (config.publishEndDatetime) {
      previewHtml += `<div style="margin-top: 8px;"><strong>掲載終了:</strong> ${config.publishEndDatetime}</div>`;
    }
    if (config.enableAutoRule) {
      previewHtml += `<div style="margin-top: 8px;"><strong>自動掲載ルール:</strong> ${config.autoRuleTrigger}</div>`;
    }
    previewHtml += '</div>';
    previewContent.innerHTML = previewHtml;
    previewModal.style.display = 'flex';
  });

  // プレビューモーダル閉じる
  closePreviewBtn.addEventListener('click', () => {
    previewModal.style.display = 'none';
  });
  cancelPreviewBtn.addEventListener('click', () => {
    previewModal.style.display = 'none';
  });

  // プレビュー確認 → 掲載実行
  confirmPreviewBtn.addEventListener('click', async () => {
    try {
      // 通知履歴に掲載実行記録を追加
      const notificationRecord = {
        顧客企業ID: currentConfig.targetCompanyId || 'all',
        通知タイプ: '自動掲載',
        通知タイトル: '契約書・提案資料・成果物が掲載されました',
        通知内容: `掲載対象: ${[currentConfig.includeContracts && '契約書', currentConfig.includeProposals && '提案資料', currentConfig.includeDeliverables && '成果物'].filter(Boolean).join(', ')}`,
        送信方法: 'ポータル画面内通知',
        送信状態: '送信済',
        送信日時: new Date().toISOString(),
        既読フラグ: false
      };
      await window.aivicApi.save(notificationHistoryIdx, notificationRecord);
      previewModal.style.display = 'none';
      alert('掲載を実行しました');
      initializePublishData();
    } catch (e) {
      console.error('Failed to execute publish:', e);
    }
  });

  // 配信失敗ログ折りたたみ
  toggleFailureLogBtn.addEventListener('click', () => {
    failureLogExpanded = !failureLogExpanded;
    failureLogPanel.style.display = failureLogExpanded ? 'block' : 'none';
    failureLogToggleIcon.textContent = failureLogExpanded ? '▼' : '▶';
  });

  // Esc キーでモーダル閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && previewModal.style.display === 'flex') {
      previewModal.style.display = 'none';
    }
  });

  // overlay クリックで閉じる
  previewModal.addEventListener('click', (e) => {
    if (e.target === previewModal) {
      previewModal.style.display = 'none';
    }
  });

  // 初期化実行
  initializePublishData();
}

function(container, apiUrl, tables) {
  const form = container.querySelector('#response-form');
  const timelineContainer = container.querySelector('#timeline-container');
  const historySearch = container.querySelector('[data-testid="history-search"]');
  const customerSearchInput = container.querySelector('#customer-search-input');
  const customerDropdown = container.querySelector('#customer-dropdown');
  const customerIdHidden = container.querySelector('[data-testid="customer-id-hidden"]');
  const contractSelect = container.querySelector('[data-testid="contract-select"]');
  const proposalSelect = container.querySelector('[data-testid="proposal-select"]');
  const deliverableCheckbox = container.querySelector('#link-deliverable');
  const invoiceCheckbox = container.querySelector('#link-invoice');
  const deliverableSelectWrapper = container.querySelector('#deliverable-select-wrapper');
  const invoiceSelectWrapper = container.querySelector('#invoice-select-wrapper');
  const deliverableSelect = container.querySelector('[data-testid="deliverable-select"]');
  const invoiceSelect = container.querySelector('[data-testid="invoice-select"]');
  const fileInput = container.querySelector('[data-testid="attachment-file"]');
  const fileList = container.querySelector('#file-list');
  const responderDisplay = container.querySelector('#responder-display');
  const errorBanner = container.querySelector('#error-banner');
  const errorText = container.querySelector('#error-text');
  const successBanner = container.querySelector('#success-banner');
  const successText = container.querySelector('#success-text');

  let allCustomers = [];
  let allContracts = [];
  let allProposals = [];
  let allDeliverables = [];
  let allInvoices = [];
  let responseHistories = [];
  let currentUserId = 'user-' + Math.random().toString(36).substr(2, 9);

  // ユーティリティ関数
  function showError(msg) {
    errorText.textContent = msg;
    errorBanner.style.display = 'block';
    setTimeout(() => { errorBanner.style.display = 'none'; }, 4000);
  }

  function showSuccess(msg) {
    successText.textContent = msg;
    successBanner.style.display = 'block';
    setTimeout(() => { successBanner.style.display = 'none'; }, 3000);
  }

  // データ初期化
  async function initializeData() {
    try {
      // テーブルインデックスの特定（テーブル名から）
      const customerTableIdx = tables.findIndex(t => t.tableName === '顧客企業');
      const contractTableIdx = tables.findIndex(t => t.tableName === '契約');
      const proposalTableIdx = tables.findIndex(t => t.tableName === '提案資料');
      const deliverableTableIdx = tables.findIndex(t => t.tableName === '成果物');
      const invoiceTableIdx = tables.findIndex(t => t.tableName === '請求書');

      // API から最新データを取得
      if (customerTableIdx >= 0) {
        allCustomers = await window.aivicApi.list(customerTableIdx) || [];
      }
      if (contractTableIdx >= 0) {
        allContracts = await window.aivicApi.list(contractTableIdx) || [];
      }
      if (proposalTableIdx >= 0) {
        allProposals = await window.aivicApi.list(proposalTableIdx) || [];
      }
      if (deliverableTableIdx >= 0) {
        allDeliverables = await window.aivicApi.list(deliverableTableIdx) || [];
      }
      if (invoiceTableIdx >= 0) {
        allInvoices = await window.aivicApi.list(invoiceTableIdx) || [];
      }

      // 対応者名を設定
      responderDisplay.textContent = '現在のユーザー';

      // 初期タイムラインを描画
      renderTimeline(responseHistories);
    } catch (err) {
      console.error('データ初期化エラー:', err);
    }
  }

  // タイムラインの描画
  function renderTimeline(histories) {
    if (histories.length === 0) {
      timelineContainer.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 12px; padding: 24px 0;">対応履歴がありません</div>';
      return;
    }

    const sorted = [...histories].sort((a, b) => new Date(b.responseDateTime) - new Date(a.responseDateTime));
    const html = sorted.map((h, idx) => {
      const customer = allCustomers.find(c => c.id === h.customerId);
      const date = new Date(h.responseDateTime);
      const dateStr = date.toLocaleDateString('ja-JP', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });

      return `
        <div style="display: flex; gap: 8px; margin-bottom: 12px; padding-bottom: 12px; border-bottom: 1px solid var(--border);" data-history-id="${h.id}">
          <div style="width: 3px; background: var(--primary); border-radius: 2px; flex-shrink: 0;"></div>
          <div style="flex: 1; min-width: 0;">
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">${dateStr}</div>
            <div style="font-size: 12px; font-weight: 500; color: var(--text); margin-bottom: 4px;">${h.responseType}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">${customer?.企業名 || '不明'}</div>
            <div style="font-size: 11px; color: var(--text); line-height: 1.4; word-break: break-word; max-height: 40px; overflow: hidden; text-overflow: ellipsis;">${h.responseContent}</div>
          </div>
        </div>
      `;
    }).join('');

    timelineContainer.innerHTML = html;
  }

  // 顧客企業検索
  customerSearchInput.addEventListener('input', (e) => {
    const query = e.target.value.toLowerCase();
    if (query.length === 0) {
      customerDropdown.style.display = 'none';
      return;
    }

    const filtered = allCustomers.filter(c => c.企業名?.toLowerCase().includes(query));
    if (filtered.length === 0) {
      customerDropdown.innerHTML = '<div style="padding: 8px; font-size: 11px; color: var(--text-muted);">該当なし</div>';
      customerDropdown.style.display = 'block';
      return;
    }

    customerDropdown.innerHTML = filtered.map(c => `
      <div style="padding: 8px; font-size: 11px; color: var(--text); cursor: pointer; border-bottom: 1px solid var(--border); transition: background 0.2s;" data-customer-id="${c.id}">
        ${c.企業名}
      </div>
    `).join('');
    customerDropdown.style.display = 'block';

    customerDropdown.querySelectorAll('[data-customer-id]').forEach(el => {
      el.addEventListener('click', () => {
        const custId = el.dataset.customerId;
        const cust = allCustomers.find(c => c.id === custId);
        customerSearchInput.value = cust?.企業名 || '';
        customerIdHidden.value = custId;
        customerDropdown.style.display = 'none';

        // 契約書を更新
        const relatedContracts = allContracts.filter(c => c.顧客企業ID === custId);
        contractSelect.innerHTML = '<option value="">選択してください</option>' + 
          relatedContracts.map(c => `<option value="${c.id}">${c.契約名}</option>`).join('');

        // 成果物を更新
        const relatedDeliverables = allDeliverables.filter(d => relatedContracts.some(c => c.id === d.契約ID));
        deliverableSelect.innerHTML = '<option value="">選択してください</option>' + 
          relatedDeliverables.map(d => `<option value="${d.id}">${d.成果物名}</option>`).join('');

        // 請求書を更新
        const relatedInvoices = allInvoices.filter(i => i.顧客企業ID === custId);
        invoiceSelect.innerHTML = '<option value="">選択してください</option>' + 
          relatedInvoices.map(i => `<option value="${i.id}">請求書 ${i.請求書番号}</option>`).join('');
      });
    });
  });

  // 提案資料ドロップダウン初期化
  proposalSelect.innerHTML = '<option value="">選択してください</option>' + 
    allProposals.map(p => `<option value="${p.id}">${p.提案資料名}</option>`).join('');

  // チェックボックス連動
  deliverableCheckbox.addEventListener('change', () => {
    deliverableSelectWrapper.style.display = deliverableCheckbox.checked ? 'block' : 'none';
  });

  invoiceCheckbox.addEventListener('change', () => {
    invoiceSelectWrapper.style.display = invoiceCheckbox.checked ? 'block' : 'none';
  });

  // ファイル選択表示
  fileInput.addEventListener('change', () => {
    const files = Array.from(fileInput.files);
    fileList.innerHTML = files.map(f => `<div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">📎 ${f.name}</div>`).join('');
  });

  // 履歴検索
  historySearch.addEventListener('input', (e) => {
    const query = e.target.value.toLowerCase();
    const filtered = responseHistories.filter(h => {
      const customer = allCustomers.find(c => c.id === h.customerId);
      return (customer?.企業名?.toLowerCase().includes(query) || 
              h.responseType?.toLowerCase().includes(query) ||
              h.responseContent?.toLowerCase().includes(query));
    });
    renderTimeline(filtered);
  });

  // フォーム送信
  form.addEventListener('submit', async (e) => {
    e.preventDefault();

    const customerId = customerIdHidden.value;
    if (!customerId) {
      showError('顧客企業を選択してください');
      return;
    }

    const formData = new FormData(form);
    const newRecord = {
      id: 'resp-' + Date.now(),
      responseDateTime: formData.get('responseDateTime'),
      responseType: formData.get('responseType'),
      customerId: customerId,
      contractId: formData.get('contractId') || null,
      responseContent: formData.get('responseContent'),
      responderId: currentUserId,
      proposalId: formData.get('proposalId') || null,
      linkDeliverable: formData.get('linkDeliverable') ? true : false,
      deliverableId: formData.get('deliverableId') || null,
      deadlineChange: formData.get('deadlineChange') ? true : false,
      linkInvoice: formData.get('linkInvoice') ? true : false,
      invoiceId: formData.get('invoiceId') || null,
      sendEmail: formData.get('sendEmail') ? true : false,
      attachmentCount: fileInput.files.length,
      createdAt: new Date().toISOString()
    };

    try {
      // 実際のテーブルインデックスを特定（対応履歴テーブルがあれば）
      const responseHistoryTableIdx = tables.findIndex(t => t.tableName?.includes('対応') || t.tableName?.includes('履歴'));

      if (responseHistoryTableIdx >= 0) {
        const saved = await window.aivicApi.save(responseHistoryTableIdx, newRecord);
        if (saved) {
          responseHistories.push(newRecord);
          renderTimeline(responseHistories);
          form.reset();
          customerSearchInput.value = '';
          customerIdHidden.value = '';
          deliverableSelectWrapper.style.display = 'none';
          invoiceSelectWrapper.style.display = 'none';
          fileList.innerHTML = '';
          showSuccess('対応内容を保存しました');
        }
      } else {
        // テーブルが無い場合はローカルに保存
        responseHistories.push(newRecord);
        renderTimeline(responseHistories);
        form.reset();
        customerSearchInput.value = '';
        customerIdHidden.value = '';
        deliverableSelectWrapper.style.display = 'none';
        invoiceSelectWrapper.style.display = 'none';
        fileList.innerHTML = '';
        showSuccess('対応内容を保存しました（ローカル）');
      }
    } catch (err) {
      console.error('保存エラー:', err);
      showError('保存に失敗しました');
    }
  });

  // 初期化実行
  initializeData();
}

function(container, apiUrl, tables) {
  const contractTable = tables[0]; // 契約
  const answerTable = tables[1]; // 回答（仮想テーブル）
  const historyTable = tables[2]; // 回答履歴（仮想テーブル）

  let selectedContractId = null;
  let selectedQuestionId = null;
  let uploadedFiles = [];

  // ===== 契約一覧の初期化 =====
  async function loadContracts() {
    const contracts = await window.aivicApi.list(0); // 契約テーブル
    if (!contracts) return;

    const contractList = container.querySelector('#contract-list');
    contractList.innerHTML = '';

    contracts.forEach(contract => {
      const item = document.createElement('div');
      item.style.cssText = `
        padding: 8px;
        border-bottom: 1px solid var(--border);
        cursor: pointer;
        font-size: 12px;
        color: var(--text);
        transition: background 0.2s;
      `;
      item.textContent = contract.契約名 || contract.contractName || '無名契約';
      item.onmouseover = () => item.style.background = 'var(--bg-hover)';
      item.onmouseout = () => item.style.background = 'transparent';
      item.onclick = () => selectContract(contract.id || contract.contractId);
      contractList.appendChild(item);
    });
  }

  // ===== 契約選択時の処理 =====
  function selectContract(contractId) {
    selectedContractId = contractId;
    selectedQuestionId = null;
    uploadedFiles = [];
    container.querySelector('#answer-text').value = '';
    container.querySelector('#file-list').innerHTML = '<div style="color: var(--text-muted);">資料なし</div>';
    container.querySelector('#question-panel').style.display = 'none';
    container.querySelector('#history-timeline').innerHTML = '<div>履歴なし</div>';

    // 実装例: 契約に紐付く質問を取得して表示
    // ここでは簡易的に質問パネルを表示
    container.querySelector('#question-panel').style.display = 'block';
    container.querySelector('#question-text').textContent = `契約「${selectedContractId}」に関する質問`;
    container.querySelector('#question-date').textContent = new Date().toLocaleDateString('ja-JP');
  }

  // ===== ファイルアップロード処理 =====
  const uploadZone = container.querySelector('#upload-zone');
  const fileInput = container.querySelector('#file-input');

  uploadZone.ondragover = (e) => {
    e.preventDefault();
    uploadZone.style.borderColor = 'var(--primary)';
    uploadZone.style.background = 'var(--bg-hover)';
  };

  uploadZone.ondragleave = () => {
    uploadZone.style.borderColor = 'var(--border)';
    uploadZone.style.background = 'var(--bg-main)';
  };

  uploadZone.ondrop = (e) => {
    e.preventDefault();
    uploadZone.style.borderColor = 'var(--border)';
    uploadZone.style.background = 'var(--bg-main)';
    handleFiles(e.dataTransfer.files);
  };

  fileInput.onchange = (e) => {
    handleFiles(e.target.files);
  };

  function handleFiles(files) {
    Array.from(files).forEach(file => {
      uploadedFiles.push({
        name: file.name,
        size: file.size,
        type: file.type,
        file: file
      });
    });
    updateFileList();
  }

  function updateFileList() {
    const fileList = container.querySelector('#file-list');
    if (uploadedFiles.length === 0) {
      fileList.innerHTML = '<div style="color: var(--text-muted);">資料なし</div>';
      return;
    }

    fileList.innerHTML = uploadedFiles.map((f, idx) => `
      <div style="padding: 6px; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between; align-items: center;">
        <div style="flex: 1;">
          <div style="color: var(--text); word-break: break-word;">${f.name}</div>
          <div style="font-size: 10px; color: var(--text-muted);">${(f.size / 1024).toFixed(1)} KB</div>
        </div>
        <button type="button" class="delete-file-btn" data-index="${idx}" style="background: transparent; border: none; color: var(--text-muted); cursor: pointer; padding: 4px; font-size: 14px;">×</button>
      </div>
    `).join('');

    container.querySelectorAll('.delete-file-btn').forEach(btn => {
      btn.onclick = (e) => {
        const idx = parseInt(e.target.dataset.index);
        uploadedFiles.splice(idx, 1);
        updateFileList();
      };
    });
  }

  // ===== 保存・公開処理 =====
  container.querySelector('#save-draft-btn').onclick = async () => {
    if (!selectedContractId) {
      alert('契約を選択してください');
      return;
    }
    const answerText = container.querySelector('#answer-text').value;
    if (!answerText.trim()) {
      alert('回答を入力してください');
      return;
    }

    const payload = {
      contractId: selectedContractId,
      answerText: answerText,
      status: 'draft',
      publishDate: null,
      publishTarget: null,
      files: uploadedFiles.map(f => f.name)
    };

    const saved = await window.aivicApi.save(1, payload);
    if (saved) {
      alert('下書きを保存しました');
      addToHistory('下書き保存', answerText);
    }
  };

  container.querySelector('#save-btn').onclick = async () => {
    if (!selectedContractId) {
      alert('契約を選択してください');
      return;
    }
    const answerText = container.querySelector('#answer-text').value;
    if (!answerText.trim()) {
      alert('回答を入力してください');
      return;
    }

    const payload = {
      contractId: selectedContractId,
      answerText: answerText,
      status: 'saved',
      publishDate: null,
      publishTarget: null,
      files: uploadedFiles.map(f => f.name)
    };

    const saved = await window.aivicApi.save(1, payload);
    if (saved) {
      alert('回答を保存しました');
      addToHistory('保存', answerText);
    }
  };

  container.querySelector('#publish-btn').onclick = async () => {
    if (!selectedContractId) {
      alert('契約を選択してください');
      return;
    }
    const answerText = container.querySelector('#answer-text').value;
    if (!answerText.trim()) {
      alert('回答を入力してください');
      return;
    }

    const publishDate = container.querySelector('#publish-date').value;
    const publishTarget = container.querySelector('#publish-target').value;
    const publishImmediately = container.querySelector('#publish-immediately').checked;

    if (!publishTarget) {
      alert('公開対象を選択してください');
      return;
    }

    const payload = {
      contractId: selectedContractId,
      answerText: answerText,
      status: publishImmediately ? 'published' : 'scheduled',
      publishDate: publishImmediately ? new Date().toISOString() : publishDate,
      publishTarget: publishTarget,
      files: uploadedFiles.map(f => f.name)
    };

    const saved = await window.aivicApi.save(1, payload);
    if (saved) {
      alert(publishImmediately ? '回答を公開しました' : '公開予定を設定しました');
      addToHistory(publishImmediately ? '公開' : '公開予定設定', answerText);
    }
  };

  container.querySelector('#back-btn').onclick = () => {
    window.showScreen('scr-1782623640991'); // ポータル確認画面へ
  };

  // ===== 履歴追加 =====
  function addToHistory(action, text) {
    const timeline = container.querySelector('#history-timeline');
    const now = new Date().toLocaleString('ja-JP');
    const entry = document.createElement('div');
    entry.style.cssText = `
      padding: 6px;
      border-left: 2px solid var(--primary);
      margin-bottom: 6px;
      padding-left: 8px;
    `;
    entry.innerHTML = `
      <div style="font-size: 11px; color: var(--primary); font-weight: 600;">${action}</div>
      <div style="font-size: 10px; color: var(--text-muted);">${now}</div>
    `;
    if (timeline.textContent === '履歴なし') {
      timeline.innerHTML = '';
    }
    timeline.insertBefore(entry, timeline.firstChild);
  }

  // 初期ロード
  loadContracts();
}
